fn count_misses(addrs: &[usize]) -> usize {
    let mut cache: Vec<usize> = Vec::new();
    let mut misses = 0;
    for a in addrs {
        let line = a / 64;
        if let Some(pos) = cache.iter().position(|&l| l == line) {
            cache.remove(pos);
        } else {
            misses += 1;
            if cache.len() == 8 {
                cache.remove(0);
            }
        }
        cache.push(line);
    }
    misses
}

